import { Injectable, Controller, Get, Post, Body } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Entity, PrimaryColumn, Column } from 'typeorm';
import * as crypto from 'crypto';

const GENESIS_HASH = '0'.repeat(64);

@Entity('audit_entries')
export class AuditEntry {
  @PrimaryColumn({ type: 'int' })
  index: number;

  @Column({ type: 'varchar', length: 64 })
  prevHash: string;

  @Column({ type: 'text' })
  payload: string;

  @Column({ type: 'varchar', length: 64 })
  entryHash: string;
}

function sha256(input: string): string {
  return crypto.createHash('sha256').update(input).digest('hex');
}

@Injectable()
export class AuditLogService {
  constructor(
    @InjectRepository(AuditEntry)
    private readonly auditRepo: Repository<AuditEntry>,
  ) {}

  /**
   * Appends a new entry to the tamper-evident hash chain.
   *
   * NOTE: reads the current tail, derives the next index/prevHash from it,
   * then inserts. Runs as three independent statements with no transaction
   * and no lock around the tail read.
   */
  async appendEntry(payload: string): Promise<AuditEntry> {
    // 1. Read the current tail row (unlocked plain SELECT).
    const tail = await this.auditRepo.findOne({
      where: {},
      order: { index: 'DESC' },
    });

    // 2. Derive the next index and the prevHash from the tail.
    const index = tail ? tail.index + 1 : 0;
    const prevHash = tail ? tail.entryHash : GENESIS_HASH;

    // 3. Compute this row's hash.
    const entryHash = sha256(`${index}:${prevHash}:${payload}`);

    // 4. Insert the new tail.
    const entry = this.auditRepo.create({ index, prevHash, payload, entryHash });
    await this.auditRepo.insert(entry);

    return entry;
  }

  /**
   * Walks the full chain in index order and asserts each row links to the
   * previous one's entryHash.
   */
  async verify(): Promise<{ valid: boolean; brokenAtIndex?: number }> {
    const rows = await this.auditRepo.find({ order: { index: 'ASC' } });

    for (let i = 1; i < rows.length; i++) {
      if (rows[i].prevHash !== rows[i - 1].entryHash) {
        return { valid: false, brokenAtIndex: rows[i].index };
      }
    }

    return { valid: true };
  }
}

@Controller('audit-log')
export class AuditLogController {
  constructor(private readonly auditLogService: AuditLogService) {}

  @Post()
  async append(@Body('payload') payload: string) {
    return this.auditLogService.appendEntry(payload);
  }

  @Get('verify')
  async verify() {
    return this.auditLogService.verify();
  }
}
